import java.io.IOException;
import java.nio.file.*;
import java.util.List;

public class Loader {
    /** Reads up to maxLines lines. Throws IOException if the file can't be read. */
    static List<String> load(Path file, int maxLines) throws IOException {   // checked: declared.
        if (maxLines < 0) throw new IllegalArgumentException("maxLines < 0");  // unchecked: caller bug.
        return Files.readAllLines(file).stream().limit(maxLines).toList();
    }

    public static void main(String[] args) {
        try {
            load(Path.of("missing.txt"), 10);
        } catch (IOException e) {                          // recoverable: use a fallback.
            System.out.println("using defaults");
        }
        try {
            load(Path.of("x"), -5);
        } catch (IllegalArgumentException | IOException e) {
            System.out.println(e.getMessage());              // maxLines < 0
        }
    }
}
```

